<!DOCTYPE html>
<html>
<head>
  <title>Conway's Game of Life</title>
  <style>
    body {
      background-color: #1e1e1e;
      display: flex;
      flex-direction: column;
      align-items: center;
      font-family: monospace;
      margin: 0;
      padding: 0;
    }

    #life {
      background-color: #282c34;
      border: 1px solid #3a4353;
      display: grid;
      grid-template-columns: repeat(40, 1fr);
      grid-template-rows: repeat(40, 1fr);
      width: 480px; /* Adjust for desired size */
      height: 480px; /* Adjust for desired size */
      margin: 20px auto;
      cursor: pointer;
    }

    .cell {
      width: 100%;
      height: 100%;
      box-sizing: border-box;
    }

    #controls {
      display: flex;
      justify-content: center;
      margin-bottom: 20px;
    }

    button {
      background-color: #3a4353;
      color: white;
      border: none;
      padding: 10px 20px;
      font-size: 16px;
      cursor: pointer;
      margin: 0 5px;
    }

    button:hover {
      background-color: #4a536b;
    }
  </style>
</head>
<body>
  <div id="controls">
    <button id="step">Step</button>
    <button id="play">Play</button>
    <button id="random">Randomize</button>
    <button id="clear">Clear</button>
  </div>

  <canvas id="life"></canvas>

  <script>
    const w = 40;
    const h = 40;
    const cells = document.getElementById('life').getElementsByClassName('cell');

    let grid = [];
    for (let i = 0; i < h; i++) {
      grid[i] = new Array(w).fill(0);
    }

    function get(x, y) {
      if (x < 0 || x >= w || y < 0 || y >= h) {
        return 0;
      }
      return grid[y][x];
    }

    function set(x, y, v) {
      grid[y][x] = v;
    }

    function step() {
      const nextGrid = [];
      for (let i = 0; i < h; i++) {
        nextGrid[i] = new Array(w).fill(0);
      }

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          let liveNeighbors = 0;
          for (let i = -1; i <= 1; i++) {
            for (let j = -1; j <= 1; j++) {
              if (i === 0 && j === 0) continue;
              liveNeighbors += get(x + j, y + i);
            }
          }

          if (get(x, y) === 1) {
            nextGrid[y][x] = (liveNeighbors >= 2 && liveNeighbors <= 3) ? 1 : 0;
          } else {
            nextGrid[y][x] = (liveNeighbors === 3) ? 1 : 0;
          }
        }
      }

      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          set(x, y, nextGrid[y][x]);
        }
      }
      render();
    }

    function clear() {
      for (let i = 0; i < h; i++) {
        for (let j = 0; j < w; j++) {
          set(j, i, 0);
        }
      }
      render();
    }


    function render() {
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const cell = cells[y * w + x];
          cell.className = 'cell';
          if (get(x, y) === 1) {
            cell.style.backgroundColor = '#3c424c'; // Darker color for alive cells
          } else {
            cell.style.backgroundColor = '#282c34'; // Default color for dead cells
          }
        }
      }
    }

    function randomSeed() {
      for (let i = 0; i < h; i++) {
        for (let j = 0; j < w; j++) {
          set(j, i, Math.random() < 0.5 ? 1 : 0);
        }
      }
      render();
    }


    document.getElementById('step').addEventListener('click', step);
    document.getElementById('play').addEventListener('click', () => {
      let intervalId = setInterval(step, 100);
      document.getElementById('play').disabled = true;
      document.getElementById('step').disabled = true;
    });

    document.getElementById('random').addEventListener('click', randomSeed);
    document.getElementById('clear').addEventListener('click', clear);


    // Initial rendering
    render();

    document.querySelector("canvas").addEventListener("mousedown", function(e) {
      const x = Math.floor((e.offsetX / 100) * w);
      const y = Math.floor((e.offsetY / 100) * h);
      set(x, y, (get(x,y) === 0)? 1 : 0);
      render();
    });

    document.querySelector("canvas").addEventListener("mouseup", function(e) {
        // Prevent accidental toggles during drag
        if (!e.buttons) {
            const x = Math.floor((e.offsetX / 100) * w);
            const y = Math.floor((e.offsetY / 100) * h);
             set(x, y, (get(x,y) === 0)? 1 : 0);

            render();
        }

    });


    document.querySelector("canvas").addEventListener("mousemove", function(e) {
      //Optional:  Add visual feedback during dragging
    });

  </script>
</body>
</html>
